import { createHash } from 'node:crypto';
import { mkdir, readFile, rename, stat, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { Injectable } from '@nestjs/common';
import { config } from '../config';

/**
 * Where 201 file documents are kept. Swappable: LocalDiskStorage for a single PC,
 * an S3 implementation (private bucket, SSE-KMS) on AWS. See docs/deploy-aws.md.
 * Keys are generated by the server ("<employeeId>/<documentId>.pdf"), never taken from user input.
 */
export abstract class DocumentStorage {
  abstract put(key: string, data: Buffer): Promise<void>;
  abstract get(key: string): Promise<Buffer>;
  abstract exists(key: string): Promise<boolean>;
}

@Injectable()
export class LocalDiskStorage extends DocumentStorage {
  private readonly root = resolve(config.documentStorageDir);

  /** Resolve a key inside the storage folder; refuses anything that would escape it. */
  private pathOf(key: string): string {
    if (!/^[\w-]+(\/[\w-]+)*\.(pdf|jpg|png)$/.test(key))
      throw new Error(`Invalid storage key ${key}`);
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root + sep)) throw new Error(`Invalid storage key ${key}`);
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathOf(key);
    await mkdir(dirname(path), { recursive: true });
    // Write to a temp file first so a crash never leaves half a document behind.
    const tmp = `${path}.${process.pid}.tmp`;
    await writeFile(tmp, data, { flag: 'wx' });
    await rename(tmp, path);
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.pathOf(key));
  }

  async exists(key: string): Promise<boolean> {
    try {
      return (await stat(this.pathOf(key))).isFile();
    } catch {
      return false;
    }
  }
}

export const sha256 = (data: Buffer) => createHash('sha256').update(data).digest('hex');

/** Detect the real file type from its first bytes (the browser-sent type can't be trusted). */
export function sniffMimeType(data: Buffer): 'application/pdf' | 'image/jpeg' | 'image/png' | null {
  if (data.subarray(0, 5).toString('latin1') === '%PDF-') return 'application/pdf';
  if (data[0] === 0xff && data[1] === 0xd8 && data[2] === 0xff) return 'image/jpeg';
  if (data.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])))
    return 'image/png';
  return null;
}

export const EXTENSION = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpg',
  'image/png': 'png',
} as const;

/** A display-safe file name: no folders, control characters or quotes; at most 120 characters. */
export function cleanFileName(name: string, ext: string): string {
  const base = (name.split(/[\\/]/).pop() ?? '')
    // eslint-disable-next-line no-control-regex -- stripping control characters is the point
    .replace(/[\u0000-\u001f\u007f"<>|:*?]/g, '')
    .trim()
    .slice(0, 120);
  const safe = base || `document.${ext}`;
  return /\.[a-z0-9]{2,4}$/i.test(safe) ? safe : `${safe}.${ext}`;
}
